function genProblem(rng, level){
  var range=level===1?10:(level===2?20:50);var t=Math.floor(rng()*4);var a,b,q,ans;
  if(t===0){a=1+Math.floor(rng()*range);b=1+Math.floor(rng()*range);q=a+' + '+b;ans=a+b;}
  else if(t===1){a=1+Math.floor(rng()*range);b=1+Math.floor(rng()*range);if(b>a){var x=a;a=b;b=x;}q=a+' - '+b;ans=a-b;}
  else if(t===2){a=2+Math.floor(rng()*(range/2));b=2+Math.floor(rng()*(range/2));q=a+' × '+b;ans=a*b;}
  else{b=2+Math.floor(rng()*9);ans=1+Math.floor(rng()*9);a=b*ans;q=a+' ÷ '+b;ans=ans;}
  return {q:q,a:ans};
}
function genSet(rng,n,level){var out=[];for(var i=0;i<n;i++)out.push(genProblem(rng,level));return out;}
var EXPORTS={genProblem:genProblem,genSet:genSet};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TimesTableForgePure = EXPORTS; }
